const items = $input.all();
let alerta = 'ALERTA STOCK BAJO - ' + new Date().toLocaleString('es-ES') + '\n\n';
for (const item of items) {
  alerta += `- ${item.json.nombre} (${item.json.referencia}): ${item.json.stock} uds (min: ${item.json.stock_minimo})\n`;
}
return [{ json: { texto_alerta: alerta, referencias: items.map(i => i.json.referencia) } }];

const stats = $('Stats del día').first().json;
const pedidos = $('Items vendidos hoy').all();

const conteo = {};
for (const p of pedidos) {
  try {
    const items = JSON.parse(p.json.items_json || '[]');
    for (const item of items) {
      const key = item.nombre || item.referencia || 'Desconocido';
      conteo[key] = (conteo[key] || 0) + (item.cantidad || 1);
    }
  } catch(e) {}
}

const top = Object.entries(conteo).sort((a,b) => b[1]-a[1]).slice(0,5);
const fecha = new Date().toLocaleDateString('es-ES', { weekday:'long', day:'numeric', month:'long' });

let resumen = `RESUMEN DEL DIA - ${fecha}\n`;
resumen += `Pedidos: ${stats.total_pedidos || 0}\n`;
resumen += `Facturado: ${(stats.facturado || 0).toFixed(2)} EUR\n`;
resumen += `Clientes: ${stats.clientes || 0}\n`;
if (top.length > 0) {
  resumen += `\nMas vendidos:\n`;
  top.forEach(([nombre, qty]) => { resumen += `  - ${nombre}: ${qty} uds\n`; });
}

return [{ json: { resumen } }];
